// Endophasia variance study arm (DESIGN.md §4). A documented before_provider_request handler.
export default function (pi: any) {
	pi.on("before_provider_request", (event: any) => undefined);
}

// Endophasia variance study arm (DESIGN.md §4). A documented before_provider_request handler.
export default function (pi: any) {
	pi.on("before_provider_request", (event: any) => ({ ...event.payload, temperature: 0, seed: 1234 }));
}

// Endophasia variance study arm (DESIGN.md §4). A documented before_provider_request handler.
export default function (pi: any) {
	pi.on("before_provider_request", (event: any) => ({ ...event.payload, temperature: 0, seed: 1234, cache_prompt: false }));
}

